def token_first(self, skip_ws=True, skip_cm=False):
    """Returns the first child token.

    If *skip_ws* is ``True`` (the default), whitespace
    tokens are ignored.

    if *skip_cm* is ``True`` (default: ``False``), comments are
    ignored too.
    """
